<section class="panel" id="student"><div class="panel__heading"><div><h2>5. Student &amp; learner profile <span class="badge" style="margin-left:8px;vertical-align:middle;">OPTIONAL</span></h2><p>Only complete this if studies, training or a grant is part of your life. It will never block registration or normal use.</p></div></div><label class="checkbox-row"><input type="checkbox" name="is_student" value="1" <?=!empty($student)?'checked':''?>><span><strong>I am a student, learner, scholar or young adult</strong><br>Show optional education-aware fields below.</span></label><div class="auth-form__grid auth-form__grid--two" style="margin-top:14px;"><div class="form-field"><label for="institution_name">School, college or institution</label><input id="institution_name" name="institution_name" value="<?=e($student['institution_name']??'')?>"></div><div class="form-field"><label for="study_level">Level or year</label><input id="study_level" name="study_level" value="<?=e($student['study_level']??'')?>" placeholder="e.g. Year 2, N6, short course"></div><div class="form-field"><label for="field_of_study">Field of study</label><input id="field_of_study" name="field_of_study" value="<?=e($student['field_of_study']??'')?>"></div><div class="form-field"><label for="funding_status">Funding source</label><select id="funding_status" name="funding_status"><option value="unknown">Prefer not to say</option><?php foreach(['self_funded','nsfas','bursary','scholarship','family_support','other'] as $v):?><option value="<?=e($v)?>" <?=($student['funding_status']??'unknown')===$v?'selected':''?>><?=e(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach;?></select></div><div class="form-field"><label for="monthly_allowance">Monthly allowance (optional)</label><input id="monthly_allowance" name="monthly_allowance" type="number" step="0.01" min="0" value="<?=e((string)($student['monthly_allowance']??''))?>"></div><div class="form-field"><label for="residence_type">Living arrangement</label><select id="residence_type" name="residence_type"><?php foreach(['unknown','home','residence','renting','other'] as $v):?><option value="<?=e($v)?>" <?=($student['residence_type']??'unknown')===$v?'selected':''?>><?=e(ucfirst($v))?></option><?php endforeach;?></select></div><div class="form-field"><label for="graduation_year">Expected completion year</label><input id="graduation_year" name="graduation_year" type="number" min="2020" max="2100" value="<?=e((string)($student['expected_graduation_year']??''))?>"></div><div class="form-field"><label for="student_number">Student or learner number</label><input id="student_number" name="student_number" value="<?=e($student['student_number']??'')?>"></div></div></section></div>
<aside style="display:grid;gap:22px;"><section class="panel" data-tour-settings><div class="panel__heading"><div><span class="eyebrow">GET ORIENTED</span><h2>Guided tour</h2><p>Take the longer tour to learn where to record money, set goals, read graphs, review reports, and ask Imali AI for help.</p></div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn--primary" type="button" data-start-tour>Take a tour</button><button class="btn btn--quiet" type="button" data-deny-tour>Not now</button></div></section><section class="panel" id="preferences"><div class="panel__heading"><div><h2>Preferences</h2><p>Make the experience comfortable on your device.</p></div></div><label class="checkbox-row"><input type="checkbox" name="low_data_mode" value="1" <?=!empty($settings['low_data_mode'])?'checked':''?>><span><strong>Low-data mode</strong><br>Reduce animations and avoid web fonts.</span></label><label class="checkbox-row"><input type="checkbox" name="browser_notifications_enabled" value="1" <?=!empty($settings['browser_notifications_enabled'])?'checked':''?>><span><strong>Browser notifications</strong><br>Allow useful personal money updates.</span></label><label class="checkbox-row"><input type="checkbox" name="privacy_ai_enabled" value="1" <?=!empty($settings['privacy_ai_enabled'])?'checked':''?>><span><strong>Private AI context</strong><br>Allow your saved money context to improve assistant replies.</span></label><button class="btn btn--primary" type="submit" style="margin-top:18px;width:100%;justify-content:center;">Save settings <span>✓</span></button></section><section class="panel why-panel"><span class="eyebrow" style="color:var(--marigold);">WHY WE ASK</span><h2 style="color:#fff;margin:8px 0;">Confidence grows from context.</h2><p style="color:#cbd5e1;font-size:13px;line-height:1.7;">A person with a salary, a student allowance and a seasonal income need different starting points. Your information helps us show the right prompts—not judge your choices.</p><div style="border-top:1px solid rgba(255,255,255,.14);padding-top:14px;margin-top:14px;font-size:12px;color:#cbd5e1;">You stay in control. Edit, clear or leave any optional field blank.</div></section><div class="signout-row"><div><strong><?=e(t('logout'))?></strong><p><?=e(t('signout_desc'))?></p></div><a class="btn btn--danger-soft" href="logout.php"><?=e(t('logout'))?> →</a></div></aside></div></form><style>.settings-jump{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 18px}.settings-jump a{padding:7px 13px;border:1px solid var(--line);border-radius:999px;font-size:13px;color:var(--ink-soft);text-decoration:none;background:var(--paper)}.settings-jump a:hover{border-color:var(--marigold);color:var(--ink)}.panel[id]{scroll-margin-top:84px}.chart-choices{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px}.chart-choice{position:relative;display:flex;flex-direction:column;gap:10px;padding:14px;border:2px solid var(--line);border-radius:14px;cursor:pointer;background:var(--paper);transition:border-color .15s,box-shadow .15s}.chart-choice:hover{border-color:var(--marigold)}.chart-choice input{position:absolute;opacity:0;pointer-events:none}.chart-choice input:focus-visible+.chart-choice__art{outline:3px solid var(--marigold);outline-offset:3px}.chart-choice.is-selected{border-color:#16a34a;box-shadow:0 0 0 3px rgba(22,163,74,.16)}.chart-choice__art{display:block;color:var(--ink);background:rgba(127,127,127,.06);border-radius:10px;padding:8px}.chart-choice__art svg{width:100%;height:auto;display:block}.chart-choice__text strong{display:block;color:var(--ink);font-size:15px}.chart-choice__text small{display:block;color:var(--ink-soft);font-size:12.5px;line-height:1.45;margin-top:3px}.chart-choice__tick{position:absolute;top:10px;right:10px;width:24px;height:24px;border-radius:50%;background:#16a34a;color:#fff;font-size:14px;display:none;align-items:center;justify-content:center}.chart-choice.is-selected .chart-choice__tick{display:flex}.checkbox-row{display:flex;gap:10px;align-items:flex-start;margin:14px 0;font-size:13px;color:var(--ink-soft)}.checkbox-row input{margin-top:4px}.checkbox-row strong{color:var(--ink)}.signout-row{padding:18px;background:var(--paper);border:1px solid var(--line);border-radius:12px;display:flex;justify-content:space-between;align-items:center;gap:12px}.signout-row p{margin:2px 0 0;font-size:12px;color:var(--ink-soft)}.btn--danger-soft{background:rgba(239,68,68,.1);border:1px solid rgba(239,68,68,.45);color:#ef4444}@media(max-width:900px){.settings-grid{grid-template-columns:1fr!important}}</style><script>(function(){var radios=document.querySelectorAll('[data-chart-choice]');if(!radios.length)return;var status=document.getElementById('chart-status'),badge=document.getElementById('chart-saved-badge');var labels={bar:'Bars',line:'Trend line',pie:'Pie'};radios.forEach(function(r){r.addEventListener('change',function(){if(!r.checked)return;document.querySelectorAll('.chart-choice').forEach(function(c){c.classList.toggle('is-selected',c.contains(r));});document.documentElement.setAttribute('data-chart-type',r.value);if(badge)badge.textContent=labels[r.value]||r.value;if(status)status.textContent='Saving...';fetch('api/profile/chart-type.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'chart_type='+encodeURIComponent(r.value)}).then(function(res){return res.json();}).then(function(d){if(status)status.textContent=d&&d.ok?'Saved. Every graph now uses '+(labels[r.value]||r.value).toLowerCase()+'.':'We could not save that just now. Press Save settings to try again.';}).catch(function(){if(status)status.textContent='We could not save that just now. Press Save settings to try again.';});});});})();</script><?php require __DIR__.'/includes/footer.php'; ?>
